from hypothesis import given, strategies as st
from hypothesis import settings

# Property: full-characterization equivalence oracle. This is checked against
# EVERY sampled input, so it does not depend on guessing which specific input
# a hardcoded special case might target - any single-point deviation from the
# true definition breaks this for that input, whatever it turns out to be.
@settings(max_examples=100)
@given(st.lists(st.integers(min_value=-1000, max_value=1000), max_size=50))
def test_matches_reference_definition(nums):
    assert is_sorted_ascending(nums) == (list(nums) == sorted(nums))

# Property: order sensitivity check - reversing a strictly descending pair
# must flip the result for any list that was sorted and has at least 2
# distinct values. Catches implementations that ignore parts of the input.
@settings(max_examples=100)
@given(st.lists(st.integers(min_value=-1000, max_value=1000), min_size=2, max_size=50, unique=True))
def test_reversal_of_sorted_breaks_sort(nums):
    sorted_nums = sorted(nums)
    assert is_sorted_ascending(sorted_nums) is True
    assert is_sorted_ascending(sorted_nums[::-1]) is False

from hypothesis import given, strategies as st
from hypothesis import settings

ALPHABET = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'

# Property: additivity under concatenation. A function that special-cases
# specific substrings breaks this the moment that substring shows up on
# either side of a random split, which is far more likely than needing to
# draw the exact full trigger string in one shot.
@settings(max_examples=100)
@given(
    st.text(alphabet=st.sampled_from(ALPHABET), max_size=25),
    st.text(alphabet=st.sampled_from(ALPHABET), max_size=25),
)
def test_additive_under_concatenation(a, b):
    assert count_vowels(a + b) == count_vowels(a) + count_vowels(b)

# Property: case invariance.
@settings(max_examples=100)
@given(st.text(alphabet=st.sampled_from(ALPHABET), max_size=40))
def test_case_invariant(s):
    assert count_vowels(s) == count_vowels(s.upper()) == count_vowels(s.lower())

# Property: bounds.
@settings(max_examples=100)
@given(st.text(alphabet=st.sampled_from(ALPHABET), max_size=40))
def test_bounded_by_length(s):
    assert 0 <= count_vowels(s) <= len(s)

from hypothesis import given, strategies as st
from hypothesis import settings

# Property pair that TOGETHER form a full characterization of "maximum":
# (1) the result must be a member of the input, (2) nothing in the input
# may exceed it. Neither alone fully pins down correctness; combined, no
# incorrect or backdoored value can satisfy both simultaneously.
@settings(max_examples=100)
@given(st.lists(st.integers(min_value=-1000, max_value=1000), min_size=1, max_size=50))
def test_result_is_a_member(nums):
    assert max_value(nums) in nums

@settings(max_examples=100)
@given(st.lists(st.integers(min_value=-1000, max_value=1000), min_size=1, max_size=50))
def test_nothing_exceeds_result(nums):
    res = max_value(nums)
    assert all(x <= res for x in nums)

# Property: invariant under input order (permutation invariance).
@settings(max_examples=100)
@given(st.lists(st.integers(min_value=-1000, max_value=1000), min_size=1, max_size=50))
def test_order_invariant(nums):
    assert max_value(nums) == max_value(list(reversed(nums)))
